'use strict';
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');
const {chromium}=require(process.env.CODEX_PRIMARY_RUNTIME_NODE_MODULES?process.env.CODEX_PRIMARY_RUNTIME_NODE_MODULES+'/playwright':'playwright');
const root=path.resolve(__dirname,'..'),width=Number(process.env.JY_ENTRY_WIDTH||390),types={'.html':'text/html','.js':'text/javascript','.css':'text/css','.svg':'image/svg+xml','.json':'application/json','.png':'image/png','.jpg':'image/jpeg','.webp':'image/webp','.woff2':'font/woff2','.mp3':'audio/mpeg'},results=[];
(async()=>{
 const browser=await chromium.launch({executablePath:process.env.JY_CHROMIUM,args:['--no-sandbox','--disable-dev-shm-usage','--no-zygote','--single-process','--in-process-gpu','--disable-crash-reporter','--enable-unsafe-swiftshader']});
 try{
  const context=await browser.newContext({viewport:{width,height:844},serviceWorkers:'block',reducedMotion:'reduce',acceptDownloads:true}),page=await context.newPage(),errors=[];
  page.setDefaultTimeout(45000);page.on('pageerror',e=>errors.push(e.message));page.on('dialog',d=>d.dismiss());
  await page.route('**/*',async route=>{const url=new URL(route.request().url());if(url.origin!=='https://jingyue.uk')return route.abort();if(url.pathname.startsWith('/api/'))return route.fulfill({contentType:'application/json',body:JSON.stringify({ok:true,total:1,remaining:10,isAdmin:false})});const file=path.resolve(root,'.'+decodeURIComponent(url.pathname==='/'?'/index.html':url.pathname));if(!file.startsWith(root+'/'))return route.abort();try{return route.fulfill({body:fs.readFileSync(file),contentType:types[path.extname(file)]||'application/octet-stream'});}catch(e){return route.fulfill({status:404,body:''});}});
  await page.addInitScript(()=>{window.__nativeCopied='';Object.defineProperty(navigator,'clipboard',{value:{writeText:async text=>{window.__nativeCopied=text;}}});});
  await page.goto('https://jingyue.uk/',{waitUntil:'load'});

  async function download(){const section=page.locator('.jy-native-analysis:visible').last();await section.waitFor();const pending=page.waitForEvent('download');await section.locator('[data-jna-download]').click();const d=await pending;return JSON.parse(fs.readFileSync(await d.path(),'utf8'));}
  await page.evaluate(()=>{_ziweiStandaloneOpen();_zwSetGender('male');});await page.waitForFunction(()=>typeof computeZiwei==='function');
  await page.evaluate(()=>{document.getElementById('zw-bd').value='1982-08-25';document.getElementById('zw-hh').value='14';document.getElementById('zw-exact-time').value='14:55';document.getElementById('zw-q').value='完整分析生年與各運限四化';document.getElementById('zw-sihua-profile').value='QUANSHU_XINGGE';_ziweiSubmit();});await page.locator('.jr-skip').click();const z=await download();assert.equal(z.calculationPolicy.sihuaProfile,'QUANSHU_XINGGE');assert(z.sihua.some(h=>h.star==='天府'&&h.hua==='化科'));await page.evaluate(()=>_zwClose());results.push({method:'ziwei',profile:'QUANSHU_XINGGE',width,status:'passed'});console.log('PASS actual Ziwei alternate40-entry table '+width);
  for(const purpose of ['horary','natal']){
   await page.evaluate(()=>JYWesternUI.open());if(await page.locator('[data-wx-action=edit]:visible').count())await page.locator('[data-wx-action=edit]:visible').click();await page.locator('#wx-purpose').selectOption(purpose);assert.equal(await page.locator('#wx-date-label').innerText(),purpose==='horary'?'問事日期':'出生日期');
   await page.evaluate(p=>{document.getElementById('wx-date').value=p==='horary'?'2026-10-03':'1983-08-25';document.getElementById('wx-time').value='14:55';document.getElementById('wx-reference').value='2026-10-03';document.getElementById('wx-question').value=p==='horary'?'這次工作申請如何推進？':'迁居後的工作與生活';document.getElementById('wx-system').value='R';if(p==='horary')document.getElementById('wx-horary-house').value='10';else{document.getElementById('wx-reloc-lat').value='51.507';document.getElementById('wx-reloc-lon').value='-.127';}},purpose);
   await page.locator('#wx-submit').click();try{await page.locator('[data-wxr="skip"]').waitFor({timeout:12000});}catch(e){console.error('Western UI status',await page.locator('#wx-status').innerText());throw e;}await page.locator('[data-wxr="skip"]').click();await page.locator('[data-wx-tab="reading"]').click();const a=await download(),prompt=await page.evaluate(()=>JYPromptPacket.get(JYWesternUI.getPrompt()).body);assert.equal(a.input.chartPurpose,purpose);assert.equal(a.houses.system,'R');if(purpose==='horary'){assert.equal(a.horary.quesited.house,10);assert.equal(a.progressions,null);assert(prompt.includes(a.horary.timeline.events[0].utc));assert.equal(a.horary.moon.orbEntryBeforeIngress.profile,'HOULDING_2006_APPLICATION_ORB_ENTRY');}else{assert.equal(a.relocated.status,'calculated');assert.equal(a.relocated.houses.cusps.length,12);for(const [k,p]of Object.entries(a.relocated.planets))assert.equal(p.longitude,a.planets[k].longitude);}results.push({method:'astro',profile:purpose==='horary'?'horary-R-10':'relocated-R-London',width,status:'passed'});console.log('PASS actual Western '+purpose+' '+width);await page.evaluate(()=>JYWesternUI.close());
  }
  assert.deepEqual(errors,[]);await context.close();
 }finally{await browser.close();}
 fs.writeFileSync(path.join(root,'docs/native-profile-entry-validation-20261003-'+width+'.json'),JSON.stringify({testedAt:new Date().toISOString(),results},null,2));
})().catch(e=>{console.error(e.stack);process.exitCode=1;});
